 $('#advancedFiltersBtn').addEventListener('click',()=>$('#advancedModal').classList.add('open'));$$('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.closeModal).classList.remove('open')));$('#advancedModal').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.classList.remove('open')});$('#applyFilters').addEventListener('click',()=>{state.category=$('#advancedCategory').value;state.startsWith=$('#startsWith').value.trim();state.minSynonyms=Number($('#minSynonyms').value||0);state.meshOnly=$('#meshOnly').value==='yes';state.displayLimit=120;syncCategoryUI();renderTerms();$('#advancedModal').classList.remove('open')});$('#resetFilters').addEventListener('click',()=>{state.category='All';state.startsWith='';state.minSynonyms=0;state.meshOnly=false;$('#startsWith').value='';$('#minSynonyms').value='0';$('#meshOnly').value='any';state.displayLimit=120;syncCategoryUI();renderTerms()});
 $('#languageControl').addEventListener('click',e=>{if(e.target.closest('.dropdown-menu button'))return;$('#languageMenu').classList.toggle('open');$('#themeMenu').classList.remove('open');$('#profileMenu').classList.remove('open')});$('#themeControl').addEventListener('click',e=>{if(e.target.closest('.dropdown-menu button'))return;$('#themeMenu').classList.toggle('open');$('#languageMenu').classList.remove('open');$('#profileMenu').classList.remove('open')});$('#profileControl').addEventListener('click',e=>{if(e.target.closest('.dropdown-menu button'))return;$('#profileMenu').classList.toggle('open');$('#languageMenu').classList.remove('open');$('#themeMenu').classList.remove('open')});document.addEventListener('click',e=>{if(!e.target.closest('.top-control'))$$('.dropdown-menu').forEach(m=>m.classList.remove('open'))});
 $('#languageMenu').addEventListener('click',e=>{const b=e.target.closest('[data-lang]');if(b){setLanguage(b.dataset.lang);$('#languageMenu').classList.remove('open')}});$('#themeMenu').addEventListener('click',e=>{const b=e.target.closest('[data-theme-choice]');if(b){setTheme(b.dataset.themeChoice);$('#themeMenu').classList.remove('open')}});
